function activeProject(){return state.projects.get(state.activeProjectId);}
function activeLayer(){return activeProject()?.layers.find(layer=>layer.id===state.activeLayerId);}
function activeFolder(){return activeProject()?.folders?.find(folder=>folder.id===state.activeFolderId);}
function selectedLayers(){const project=activeProject();if(!project)return [];const selected=project.layers.filter(layer=>state.selectedLayerIds.has(layer.id));return selected.length?selected:(activeLayer()?[activeLayer()]:[]);}
function selectOnlyLayer(id){state.activeLayerId=id||null;state.activeFolderId=null;state.selectedLayerIds=new Set(id?[id]:[]);state.selectedFolderIds.clear();}
function selectOnlyFolder(id){state.activeLayerId=null;state.activeFolderId=id||null;state.selectedLayerIds.clear();state.selectedFolderIds=new Set(id?[id]:[]);}
function selectLayerFromPanel(event,layer,ordered){if(event.shiftKey&&state.activeLayerId){const from=ordered.findIndex(item=>item.id===state.activeLayerId),to=ordered.findIndex(item=>item.id===layer.id);if(from>=0&&to>=0){state.selectedLayerIds=new Set(ordered.slice(Math.min(from,to),Math.max(from,to)+1).map(item=>item.id));state.activeLayerId=layer.id;return;}}if(event.ctrlKey||event.metaKey){if(state.selectedLayerIds.has(layer.id)){state.selectedLayerIds.delete(layer.id);if(state.activeLayerId===layer.id)state.activeLayerId=state.selectedLayerIds.values().next().value||null;}else{state.selectedLayerIds.add(layer.id);state.activeLayerId=layer.id;}return;}selectOnlyLayer(layer.id);}
function topLayer(project){return project?.layers.reduce((top,layer)=>!top||layer.z_index>top.z_index?layer:top,null);}
function nextProjectId(){return `document-${state.nextProjectId++}`;}
function nextLayerId(){return `layer-${state.nextLayerId++}`;}
function nextFolderId(){return `folder-${state.nextFolderId++}`;}
function clonePlain(value){return value==null?value:JSON.parse(JSON.stringify(value));}
function escapeHtml(value){const div=document.createElement('div');div.textContent=String(value);return div.innerHTML;}
function iconUrl(icon){return `${iconBase}${icon}.png`;}
function iconMarkup(icon,className='ps-icon',alt=''){return `<img class="${className}" src="${iconUrl(icon)}" alt="${escapeHtml(alt)}">`;}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,3600);}
function setBusy(value){state.busy=value;updateSaveUi();}

function projectSnapshot(project){return {name:project.name,width:project.width,height:project.height,layers:project.layers.map(layer=>({...layer,textData:clonePlain(layer.textData)})),folders:(project.folders||[]).map(folder=>({...folder}))};}
function projectSignature(project){return JSON.stringify({name:project.name,width:project.width,height:project.height,folders:(project.folders||[]).map(({id,name,parentId,order,visible,expanded,opacity,blendMode})=>({id,name,parentId,order,visible,expanded,opacity,blendMode})),layers:project.layers.map(({id,name,x,y,width,height,original_width,original_height,rotation,opacity,visible,z_index,type,text,blendMode,parentId,order})=>({id,name,x,y,width,height,original_width,original_height,rotation,opacity,visible,z_index,type,text,blendMode,parentId,order}))});}
function historyFor(project){if(!state.histories.has(project.id))state.histories.set(project.id,{entries:[],index:-1});return state.histories.get(project.id);}
function historyIcon(label){if(/move|align/i.test(label))return 'tools-move';if(/rotate/i.test(label))return 'rotate';if(/transform|resize|opacity|aspect/i.test(label))return 'tools-transform';if(/paste|layer|new|text/i.test(label))return 'lrs-newlayer';if(/open/i.test(label))return 'pix_layer';return 'panels-history';}
function initializeHistory(project,label,clean=false){state.histories.set(project.id,{entries:[{label,icon:historyIcon(label),snapshot:projectSnapshot(project)}],index:0});state.savedSignatures.set(project.id,clean?projectSignature(project):null);refreshDirty(project);}
function recordProjectHistory(project,label){const history=historyFor(project);if(history.index<history.entries.length-1)history.entries.splice(history.index+1);history.entries.push({label,icon:historyIcon(label),snapshot:projectSnapshot(project)});if(history.entries.length>100)history.entries.shift();history.index=history.entries.length-1;refreshDirty(project);if(project.id===state.activeProjectId)renderHistory();}
function recordHistory(label){const project=activeProject();if(project)recordProjectHistory(project,label);}
function restoreHistoryTo(index){const project=activeProject();if(!project)return;const history=historyFor(project);if(index<0||index>=history.entries.length||index===history.index)return;history.index=index;const snapshot=history.entries[index].snapshot;project.name=snapshot.name;project.width=snapshot.width??project.width;project.height=snapshot.height??project.height;project.layers=snapshot.layers.map(layer=>({...layer,textData:clonePlain(layer.textData)}));project.folders=(snapshot.folders||[]).map(folder=>({...folder}));normalizeProjectTree(project);state.selectedLayerIds=new Set([...state.selectedLayerIds].filter(id=>project.layers.some(layer=>layer.id===id)));state.selectedFolderIds=new Set([...state.selectedFolderIds].filter(id=>project.folders.some(folder=>folder.id===id)));if(!project.layers.some(layer=>layer.id===state.activeLayerId)&&!project.folders.some(folder=>folder.id===state.activeFolderId))selectOnlyLayer(topLayer(project)?.id||null);refreshDirty(project);render();}function restoreHistory(direction){const project=activeProject();if(project)restoreHistoryTo(historyFor(project).index+direction);}
function refreshDirty(project){const dirty=projectSignature(project)!==state.savedSignatures.get(project.id);state.dirtyProjects[dirty?'add':'delete'](project.id);updateSaveUi();}
function updateSaveUi(){const project=activeProject(),status=document.getElementById('saveStatus'),button=document.getElementById('saveButton');if(!project){status.textContent='No document';button.hidden=true;return;}status.textContent=state.busy?'Working locally…':state.dirtyProjects.has(project.id)?'Unsaved changes':'Saved locally';button.hidden=!state.dirtyProjects.has(project.id);button.disabled=state.busy;}

function treeItemParent(item){return item.parentId||null;}
function treeChildren(project,parentId=null){
    const parent=parentId||null,folders=(project.folders||[]).filter(folder=>treeItemParent(folder)===parent).map(folder=>({kind:'folder',item:folder})),layers=project.layers.filter(layer=>treeItemParent(layer)===parent).map(layer=>({kind:'layer',item:layer}));
    return [...folders,...layers].sort((a,b)=>{const aOrder=Number(a.item.order),bOrder=Number(b.item.order),aHas=Number.isFinite(aOrder),bHas=Number.isFinite(bOrder);if(aHas&&bHas&&aOrder!==bOrder)return aOrder-bOrder;if(aHas!==bHas)return aHas?-1:1;if(a.kind!==b.kind)return a.kind==='folder'?-1:1;return Number(b.item.z_index||0)-Number(a.item.z_index||0);});
}
function normalizeProjectTree(project){
    project.folders=project.folders||[];const folderIds=new Set(project.folders.map(folder=>folder.id));project.folders.forEach(folder=>{if(folder.parentId&&!folderIds.has(folder.parentId))folder.parentId=null;});project.layers.forEach(layer=>{if(layer.parentId&&!folderIds.has(layer.parentId))layer.parentId=null;});
    const leaves=[],visited=new Set();const walk=(parentId=null,ancestors=new Set())=>{treeChildren(project,parentId).forEach(({kind,item},order)=>{item.order=order;if(kind==='folder'){if(ancestors.has(item.id))return;visited.add(item.id);walk(item.id,new Set([...ancestors,item.id]));}else leaves.push(item);});};walk();
    project.folders.filter(folder=>!visited.has(folder.id)).forEach(folder=>folder.parentId=null);if(project.folders.some(folder=>!visited.has(folder.id))){visited.clear();leaves.length=0;walk();}
    leaves.forEach((layer,index)=>layer.z_index=leaves.length-1-index);return project;
}
function folderAncestors(project,parentId){const result=[];let current=parentId;while(current){const folder=(project.folders||[]).find(item=>item.id===current);if(!folder||result.includes(folder))break;result.push(folder);current=folder.parentId;}return result;}
function layerIsVisible(project,layer){return layer.visible&&folderAncestors(project,layer.parentId).every(folder=>folder.visible);}
function effectiveLayerOpacity(project,layer){return folderAncestors(project,layer.parentId).reduce((opacity,folder)=>opacity*(Number(folder.opacity??100)/100),Number(layer.opacity)/100);}
function panelTreeRows(project,parentId=null,depth=0,result=[]){treeChildren(project,parentId).forEach(node=>{result.push({...node,depth});if(node.kind==='folder'&&node.item.expanded!==false)panelTreeRows(project,node.item.id,depth+1,result);});return result;}
function findTreeNode(project,kind,id){const collection=kind==='folder'?(project.folders||[]):project.layers;const item=collection.find(candidate=>candidate.id===id);return item?{kind,item}:null;}
function folderContains(project,folderId,candidateId){let current=(project.folders||[]).find(folder=>folder.id===candidateId);while(current){if(current.parentId===folderId)return true;current=(project.folders||[]).find(folder=>folder.id===current.parentId);}return false;}
function newLayer(project,{name='Layer',dataUrl,x=0,y=0,width,height,rotation=0,opacity=100,visible=true,z_index,type='pixel',text=null,textData=null,blendMode='normal',parentId=null,order=null}){
    return {id:nextLayerId(),name,image_url:dataUrl,x:Number(x),y:Number(y),width:Number(width),height:Number(height),original_width:Number(width),original_height:Number(height),rotation:Number(rotation),opacity:Number(opacity),visible:Boolean(visible),z_index:z_index??project.layers.length,type,text,textData:clonePlain(textData),text_origin_x:Number(x),text_origin_y:Number(y),blendMode,parentId,order};
}

function createLocalProject({name,width,height,layers=[],folders=[],historyLabel='New',clean=false}){
    const project={id:nextProjectId(),name,width:Number(width),height:Number(height),layers,folders};normalizeProjectTree(project);
    state.projects.set(project.id,project);state.tabs.push(project.id);state.activeProjectId=project.id;selectOnlyLayer(topLayer(project)?.id||null);state.zooms.set(project.id,1);state.zoom=1;initializeHistory(project,historyLabel,clean);render();requestAnimationFrame(fitScreen);return project;
}

function canvasToDataUrl(canvas){return canvas.toDataURL('image/png');}
function transparentCanvas(width,height){const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(width));canvas.height=Math.max(1,Math.round(height));return canvas;}
async function loadImage(src){return new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(new Error('Could not decode a local layer image.'));image.src=src;});}
async function imageFileToPng(file){const bitmap=await createImageBitmap(file);if(bitmap.width>8192||bitmap.height>8192){bitmap.close();throw new Error('Images are limited to 8192 × 8192 pixels.');}const canvas=transparentCanvas(bitmap.width,bitmap.height);canvas.getContext('2d').drawImage(bitmap,0,0);bitmap.close();return {dataUrl:canvasToDataUrl(canvas),width:canvas.width,height:canvas.height};}

function countPsdLayers(children=[]){return children.reduce((count,layer)=>count+(layer.children?countPsdLayers(layer.children):1),0);}
function importPsdTree(children,project,parentId=null){
    (children||[]).forEach((source,order)=>{
        if(Array.isArray(source.children)){
            const folder={id:nextFolderId(),name:source.name||'Group',parentId,order,visible:!Boolean(source.hidden),expanded:source.opened!==false,opacity:Math.round((source.opacity??1)*100),blendMode:source.blendMode||'pass through'};project.folders.push(folder);importPsdTree(source.children,project,folder.id);return;
        }
        const canvas=source.canvas||('text' in source?renderTextCanvas(source.text):transparentCanvas(Math.max(1,(source.right||1)-(source.left||0)),Math.max(1,(source.bottom||1)-(source.top||0))));
        const x=Number(source.left)||0,y=Number(source.top)||0,layer=newLayer(project,{name:source.name||'Layer',dataUrl:canvasToDataUrl(canvas),x,y,width:canvas.width,height:canvas.height,opacity:Math.round((source.opacity??1)*100),visible:!Boolean(source.hidden),type:source.text?'text':'pixel',text:source.text?.text||null,textData:source.text||null,blendMode:source.blendMode||'normal',parentId,order});
        layer.text_origin_x=x;layer.text_origin_y=y;project.layers.push(layer);
    });
}const cssBlendModes={normal:'normal',dissolve:'normal',darken:'darken',multiply:'multiply','color burn':'color-burn','linear burn':'multiply','darker color':'darken',lighten:'lighten',screen:'screen','color dodge':'color-dodge','linear dodge':'plus-lighter','lighter color':'lighten',overlay:'overlay','soft light':'soft-light','hard light':'hard-light','vivid light':'hard-light','linear light':'hard-light','pin light':'hard-light','hard mix':'hard-light',difference:'difference',exclusion:'exclusion',subtract:'difference',divide:'exclusion',hue:'hue',saturation:'saturation',color:'color',luminosity:'luminosity'};
function cssBlendMode(mode){return cssBlendModes[mode]||'normal';}
function canvasBlendMode(mode){const value=cssBlendMode(mode);return value==='plus-lighter'?'lighter':value;}
function colorCss(color){if(!color)return '#000000';const channel=value=>Math.max(0,Math.min(255,Math.round(Number(value)||0)));return `rgb(${channel(color.r)},${channel(color.g)},${channel(color.b)})`;}
function renderTextCanvas(textData){const text=String(textData?.text||'Text');const fontSize=Math.max(1,Number(textData?.style?.fontSize)||36);const lines=text.split(/\r?\n/);const probe=transparentCanvas(1,1),ctx=probe.getContext('2d');ctx.font=`${fontSize}px Arial`;const width=Math.max(2,Math.ceil(Math.max(...lines.map(line=>ctx.measureText(line||' ').width))+8));const lineHeight=Math.ceil(fontSize*1.25),height=Math.max(2,lineHeight*lines.length+6);const canvas=transparentCanvas(width,height),draw=canvas.getContext('2d');draw.font=`${fontSize}px Arial`;draw.textBaseline='top';draw.fillStyle=colorCss(textData?.style?.fillColor);lines.forEach((line,index)=>draw.fillText(line,4,3+index*lineHeight));return canvas;}

async function openPsdFile(file){
    const buffer=await file.arrayBuffer();
    const structure=readPsd(buffer,{skipLayerImageData:true,skipCompositeImageData:true,skipThumbnail:true});
    if(structure.width>8192||structure.height>8192)throw new Error('PSD documents are limited to 8192 × 8192 pixels.');
    if(countPsdLayers(structure.children)>500)throw new Error('PSD documents are limited to 500 layers.');
    const psd=readPsd(buffer,{skipThumbnail:true});
    const project={id:nextProjectId(),name:file.name.replace(/\.psd$/i,''),width:psd.width,height:psd.height,layers:[],folders:[]};
    importPsdTree(psd.children,project);normalizeProjectTree(project);
    if(!project.layers.length&&psd.canvas){project.layers.push(newLayer(project,{name:'Background',dataUrl:canvasToDataUrl(psd.canvas),width:psd.canvas.width,height:psd.canvas.height,z_index:0,order:0}));}
    return createLocalProject({...project,historyLabel:'Open PSD',clean:true});
}
async function openRasterFile(file){const png=await imageFileToPng(file);const project={id:nextProjectId(),name:file.name.replace(/\.[^.]+$/,''),width:png.width,height:png.height,layers:[]};project.layers.push(newLayer(project,{name:file.name,dataUrl:png.dataUrl,width:png.width,height:png.height,z_index:0}));return createLocalProject({...project,historyLabel:'Open Image',clean:false});}
async function openLocalFile(file){state.loadingFile={name:file.name};switchPanel('layers');renderLayers();setBusy(true);try{return file.name.toLowerCase().endsWith('.psd')?await openPsdFile(file):await openRasterFile(file);}finally{state.loadingFile=null;setBusy(false);renderLayers();}}

async function placeImageFile(file){const project=activeProject();if(!project)throw new Error('Open a document before placing an image.');const png=await imageFileToPng(file),x=(project.width-png.width)/2,y=(project.height-png.height)/2;return addLayer(project,png.dataUrl,png.width,png.height,file.name,x,y,'Place Image');}
async function placeLocalImage(file){state.loadingFile={name:file.name,status:'Placing at original size…'};switchPanel('layers');renderLayers();setBusy(true);try{return await placeImageFile(file);}finally{state.loadingFile=null;setBusy(false);renderLayers();}}
async function layerCanvasForExport(layer){
    const image=await loadImage(layer.image_url),width=Math.max(1,Math.round(layer.width)),height=Math.max(1,Math.round(layer.height)),angle=Number(layer.rotation)||0;
    if(!angle){const canvas=transparentCanvas(width,height);canvas.getContext('2d').drawImage(image,0,0,width,height);return {canvas,left:Math.round(layer.x),top:Math.round(layer.y)};}
    const radians=angle*Math.PI/180,cos=Math.abs(Math.cos(radians)),sin=Math.abs(Math.sin(radians)),boxWidth=Math.max(1,Math.ceil(width*cos+height*sin)),boxHeight=Math.max(1,Math.ceil(width*sin+height*cos));
    const canvas=transparentCanvas(boxWidth,boxHeight),ctx=canvas.getContext('2d');ctx.translate(boxWidth/2,boxHeight/2);ctx.rotate(radians);ctx.drawImage(image,-width/2,-height/2,width,height);
    return {canvas,left:Math.round(layer.x-(boxWidth-width)/2),top:Math.round(layer.y-(boxHeight-height)/2)};
}
function exportTextData(layer){const text=clonePlain(layer.textData)||{text:layer.text||'Text',style:{font:{name:'ArialMT'},fontSize:36,fillColor:{r:0,g:0,b:0}}};text.text=layer.text||text.text||'Text';const transform=Array.isArray(text.transform)&&text.transform.length>=6?[...text.transform]:[1,0,0,1,layer.x,layer.y+(Number(text.style?.fontSize)||36)];transform[4]+=layer.x-(layer.text_origin_x??layer.x);transform[5]+=layer.y-(layer.text_origin_y??layer.y);text.transform=transform;return text;}
async function renderComposite(project,layers=project.layers){const canvas=transparentCanvas(project.width,project.height),ctx=canvas.getContext('2d');for(const layer of [...layers].sort((a,b)=>a.z_index-b.z_index)){if(!layerIsVisible(project,layer))continue;const image=await loadImage(layer.image_url);ctx.save();ctx.globalAlpha=effectiveLayerOpacity(project,layer);ctx.globalCompositeOperation=canvasBlendMode(layer.blendMode);ctx.translate(layer.x+layer.width/2,layer.y+layer.height/2);ctx.rotate(layer.rotation*Math.PI/180);ctx.drawImage(image,-layer.width/2,-layer.height/2,layer.width,layer.height);ctx.restore();}return canvas;}
