function beginItemRename(item,label,row,historyLabel){const input=document.createElement('input');input.className='ps-layer-name-input';input.value=item.name;label.replaceWith(input);row.draggable=false;input.focus();input.select();let finished=false;const finish=commit=>{if(finished)return;finished=true;const name=input.value.trim();if(commit&&name&&name!==item.name){item.name=name;recordHistory(historyLabel);render();}else renderLayers();};input.addEventListener('click',event=>event.stopPropagation());input.addEventListener('dblclick',event=>event.stopPropagation());input.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();finish(true);}if(event.key==='Escape'){event.preventDefault();finish(false);}});input.addEventListener('blur',()=>finish(true));}
