function buildTools(){const panel=document.getElementById('toolsPanel');toolGroups.forEach(group=>{group.activeId=group.tools[0].id;const wrapper=document.createElement('div');wrapper.className=`ps-tool-group${group.id==='move'?' active':''}`;wrapper.dataset.toolGroup=group.id;const main=document.createElement('button');main.type='button';main.className='ps-tool';main.dataset.tool=group.activeId;main.title=group.tools[0].name;main.innerHTML=`${iconMarkup(group.tools[0].icon,'ps-tool-icon')}<kbd>${group.key}</kbd>`;wrapper.append(main);if(group.tools.length>1){const toggle=document.createElement('button');toggle.type='button';toggle.className='ps-tool-flyout-toggle';toggle.innerHTML=iconMarkup('lrs-arrow_right','ps-tool-flyout-arrow');const flyout=document.createElement('div');flyout.className='ps-tool-flyout';group.tools.forEach(tool=>{const item=document.createElement('button');item.type='button';item.className='ps-tool-flyout-item';item.dataset.tool=tool.id;item.innerHTML=`${iconMarkup(tool.icon,'ps-tool-icon')}<span>${escapeHtml(tool.name)}</span><kbd>${group.key}</kbd>`;flyout.append(item);});toggle.addEventListener('click',event=>{event.stopPropagation();const opening=!wrapper.classList.contains('open');closeToolFlyouts();wrapper.classList.toggle('open',opening);});wrapper.addEventListener('contextmenu',event=>{event.preventDefault();closeToolFlyouts();wrapper.classList.add('open');});wrapper.append(toggle,flyout);}panel.append(wrapper);});}
function selectTool(tool){const meta=toolMeta(tool);if(!meta)return;meta.group.activeId=tool;state.tool=tool;document.querySelectorAll('.ps-tool-group').forEach(wrapper=>wrapper.classList.toggle('active',wrapper.dataset.toolGroup===meta.group.id));const groupButton=document.querySelector(`[data-tool-group="${meta.group.id}"] > .ps-tool`);if(groupButton){groupButton.dataset.tool=tool;groupButton.title=meta.name;groupButton.innerHTML=`${iconMarkup(meta.icon,'ps-tool-icon')}<kbd>${meta.group.key}</kbd>`;}document.getElementById('activeToolIcon').innerHTML=iconMarkup(meta.icon);document.getElementById('activeToolName').textContent=meta.name;closeToolFlyouts();if(!['move','marquee','zoom','zoom-in','zoom-out','horizontal-type'].includes(tool))toast(`${meta.name} will be added in a later version.`);updateMoveable();}

function renderTemplateCategories(){const nav=document.getElementById('templateCategories');nav.replaceChildren(...documentTemplateCategories.map(category=>{const button=document.createElement('button');button.type='button';button.textContent=category.label;button.classList.toggle('active',category.id===activeTemplateCategory);button.addEventListener('click',()=>{activeTemplateCategory=category.id;selectedDocumentTemplateId=null;renderTemplateCategories();renderTemplateGrid();});return button;}));}
function renderTemplateGrid(){const grid=document.getElementById('templateGrid'),category=documentTemplateCategories.find(item=>item.id===activeTemplateCategory);grid.replaceChildren(...(category?.templates||[]).map(template=>{const card=document.createElement('button');card.type='button';card.className='ps-template-card';card.classList.toggle('selected',template.id===selectedDocumentTemplateId);const scale=Math.min(166/Number(template.width),106/Number(template.height)),preview=document.createElement('span');preview.className='ps-template-preview';preview.style.width=`${Math.max(2,Number(template.width)*scale)}px`;preview.style.height=`${Math.max(2,Number(template.height)*scale)}px`;const title=document.createElement('strong');title.textContent=template.title||'';title.hidden=!template.title;const dimensions=document.createElement('span');dimensions.className='ps-template-dimensions';dimensions.textContent=template.display;card.append(preview,title,dimensions);card.addEventListener('click',()=>selectDocumentTemplate(template));return card;}));}
function selectDocumentTemplate(template){selectedDocumentTemplateId=template.id;document.getElementById('projectWidth').value=template.width;document.getElementById('projectHeight').value=template.height;document.getElementById('documentUnit').value=template.unit;document.getElementById('documentDpi').value=template.dpi;renderTemplateGrid();}
function documentPixelDimensions(){const width=Number(document.getElementById('projectWidth').value),height=Number(document.getElementById('projectHeight').value),dpi=Number(document.getElementById('documentDpi').value),unit=document.getElementById('documentUnit').value,multiplier=unit==='in'?dpi:unit==='mm'?dpi/25.4:1;return {width:Math.round(width*multiplier),height:Math.round(height*multiplier)};}
async function loadDocumentTemplates(){const response=await fetch('/photoshop-templates.json');if(!response.ok)throw new Error('Could not load document templates.');documentTemplateCategories=(await response.json()).categories||[];activeTemplateCategory=documentTemplateCategories[0]?.id||'social';renderTemplateCategories();renderTemplateGrid();}

document.addEventListener('click',event=>{if(!event.target.closest('.ps-menu'))closeMenus();if(!event.target.closest('.ps-tool-group'))closeToolFlyouts();if(!event.target.closest('#opacityControl'))document.getElementById('opacityPopover').hidden=true;const action=event.target.closest('[data-action]')?.dataset.action;if(action)actions[action]?.();const tool=event.target.closest('[data-tool]')?.dataset.tool;if(tool)selectTool(tool);const panel=event.target.closest('[data-panel-tab]')?.dataset.panelTab;if(panel)switchPanel(panel);const align=event.target.closest('[data-align-layer]')?.dataset.alignLayer;if(align)alignActiveLayers(align);});
document.addEventListener('keydown',event=>{const mod=event.ctrlKey||event.metaKey,key=event.key.toLowerCase();if(mod&&key==='z'){event.preventDefault();event.shiftKey?actions.redo():actions.undo();return;}if(mod&&key==='y'){event.preventDefault();actions.redo();return;}if(mod&&key==='s'){event.preventDefault();exportActiveProjectAsPsd();return;}if(mod&&(key==='+'||key==='=')){event.preventDefault();actions.zoomIn();return;}if(mod&&key==='-'){event.preventDefault();actions.zoomOut();return;}if(['INPUT','SELECT','TEXTAREA'].includes(event.target.tagName))return;let action=null;if(mod&&key==='n')action='newProject';if(mod&&key==='o')action='openLocal';if(mod&&key==='a')action='selectAll';if(mod&&key==='c')action='copy';if(mod&&key==='v')action='paste';if(mod&&key==='d')action='deselect';if(mod&&event.key==='0')action='fitScreen';if(mod&&event.key==='1')action='actualPixels';if(action){event.preventDefault();actions[action]?.();}if(!mod&&['v','m','t','z'].includes(key))selectTool(key==='m'?'marquee':key==='v'?'move':key==='t'?'horizontal-type':'zoom');if(!mod&&event.key==='Delete'){event.preventDefault();actions.deleteLayers();}});
document.getElementById('newProjectForm').addEventListener('submit',event=>{event.preventDefault();if(event.submitter?.value==='cancel'){document.getElementById('newProjectDialog').close();return;}const dimensions=documentPixelDimensions();if(dimensions.width<1||dimensions.height<1||dimensions.width>8192||dimensions.height>8192){toast('Document dimensions must resolve to between 1 and 8,192 pixels.');return;}const project={id:nextProjectId(),name:document.getElementById('newProjectName').value,width:dimensions.width,height:dimensions.height,layers:[]},canvas=transparentCanvas(dimensions.width,dimensions.height);project.layers.push(newLayer(project,{name:'Layer 1',dataUrl:canvasToDataUrl(canvas),width:dimensions.width,height:dimensions.height,z_index:0}));createLocalProject({...project,historyLabel:'New',clean:false});document.getElementById('newProjectDialog').close();});
document.getElementById('swapDimensions').addEventListener('click',()=>{const width=document.getElementById('projectWidth'),height=document.getElementById('projectHeight'),next=width.value;width.value=height.value;height.value=next;selectedDocumentTemplateId=null;renderTemplateGrid();});
for(const id of ['projectWidth','projectHeight','documentUnit','documentDpi'])document.getElementById(id).addEventListener('input',()=>{selectedDocumentTemplateId=null;renderTemplateGrid();});
document.getElementById('localFileInput').addEventListener('change',async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;try{await openLocalFile(file);}catch(error){toast(error.message||'Could not open that local file.');}});
document.getElementById('placeImageInput').addEventListener('change',async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;try{await placeLocalImage(file);}catch(error){toast(error.message||'Could not place that image.');}});
const imageSizeWidth=document.getElementById('imageSizeWidth'),imageSizeHeight=document.getElementById('imageSizeHeight'),imageSizeLock=document.getElementById('imageSizeLock');
imageSizeWidth.addEventListener('input',()=>{if(imageSizeLock.checked)imageSizeHeight.value=Math.max(1,Math.round((Number(imageSizeWidth.value)||1)/imageSizeRatio));updateImageSizeReadout();});
imageSizeHeight.addEventListener('input',()=>{if(imageSizeLock.checked)imageSizeWidth.value=Math.max(1,Math.round((Number(imageSizeHeight.value)||1)*imageSizeRatio));updateImageSizeReadout();});
document.getElementById('imageSizeForm').addEventListener('submit',event=>{event.preventDefault();if(event.submitter?.value==='confirm')applyImageSize(imageSizeWidth.value,imageSizeHeight.value);else document.getElementById('imageSizeDialog').close();});
document.querySelectorAll('[data-canvas-anchor]').forEach(button=>button.addEventListener('click',()=>setCanvasAnchor(button.dataset.canvasAnchor)));
document.getElementById('canvasSizeRelative').addEventListener('change',event=>{const project=activeProject();if(!project)return;document.getElementById('canvasSizeWidth').value=event.target.checked?0:project.width;document.getElementById('canvasSizeHeight').value=event.target.checked?0:project.height;});
document.getElementById('canvasSizeForm').addEventListener('submit',event=>{event.preventDefault();if(event.submitter?.value==='confirm')applyCanvasSize(document.getElementById('canvasSizeWidth').value,document.getElementById('canvasSizeHeight').value,document.getElementById('canvasSizeRelative').checked);else document.getElementById('canvasSizeDialog').close();});
document.querySelector('[data-close-layerize-history]').addEventListener('click',()=>document.getElementById('layerizeHistoryDialog').close());
document.getElementById('deleteLayersForm').addEventListener('submit',event=>{event.preventDefault();if(event.submitter?.value==='delete')deleteSelectedItems();else document.getElementById('deleteLayersDialog').close();});
const opacityInput=document.getElementById('layerOpacity'),opacitySlider=document.getElementById('layerOpacitySlider'),opacityPopover=document.getElementById('opacityPopover');
function showOpacitySlider(){if(activeLayer())opacityPopover.hidden=false;}
document.getElementById('opacityTrigger').addEventListener('click',()=>{if(activeLayer())opacityPopover.hidden=!opacityPopover.hidden;});
opacityInput.addEventListener('click',showOpacitySlider);
opacityInput.addEventListener('change',event=>{const layer=activeLayer();if(!layer)return;const value=Math.max(0,Math.min(100,Number(event.target.value)||0));event.target.value=value;opacitySlider.value=value;updateLayer(layer,{opacity:value},'Opacity Change').then(renderCanvas);});
opacitySlider.addEventListener('focus',()=>{const layer=activeLayer();if(layer)opacitySlider.dataset.start=String(layer.opacity);});
opacitySlider.addEventListener('pointerdown',()=>{const layer=activeLayer();if(layer)opacitySlider.dataset.start=String(layer.opacity);});
opacitySlider.addEventListener('input',event=>{const layer=activeLayer();if(!layer)return;layer.opacity=Number(event.target.value);opacityInput.value=event.target.value;refreshDirty(activeProject());renderCanvas();renderProperties();});
opacitySlider.addEventListener('change',()=>{const layer=activeLayer();if(layer&&Number(opacitySlider.dataset.start)!==layer.opacity)recordHistory('Opacity Change');});
document.getElementById('layerBlendMode').addEventListener('change',event=>{const layer=activeLayer();if(layer)updateLayer(layer,{blendMode:event.target.value},'Blending Change').then(renderCanvas);});
document.getElementById('transformControls').addEventListener('change',updateMoveable);
document.getElementById('propertiesPanel').addEventListener('change',event=>{const input=event.target.closest('[data-layer-property]'),layer=activeLayer();if(!input||!layer)return;const property=input.dataset.layerProperty,value=Number(input.value);if(Number.isFinite(value))updateLayer(layer,{[property]:value},property==='opacity'?'Opacity Change':'Transform').then(render);});
document.getElementById('canvas').addEventListener('pointerdown',event=>{const canvas=event.currentTarget,rect=canvas.getBoundingClientRect(),point={x:(event.clientX-rect.left)/state.zoom,y:(event.clientY-rect.top)/state.zoom};if(state.tool==='horizontal-type'){addTextLayerAt(point.x,point.y);return;}if(['zoom','zoom-in','zoom-out'].includes(state.tool)){const zoomOut=state.tool==='zoom-out'||(state.tool==='zoom'&&event.altKey);setZoom(state.zoom*(zoomOut ? .8 : 1.25));return;}if(state.tool!=='marquee')return;const start=point;canvas.setPointerCapture(event.pointerId);const move=next=>{const x=(next.clientX-rect.left)/state.zoom,y=(next.clientY-rect.top)/state.zoom;selectArea({x:Math.max(0,Math.min(start.x,x)),y:Math.max(0,Math.min(start.y,y)),width:Math.min(activeProject().width,Math.abs(x-start.x)),height:Math.min(activeProject().height,Math.abs(y-start.y))});};const up=()=>{canvas.removeEventListener('pointermove',move);canvas.removeEventListener('pointerup',up);};canvas.addEventListener('pointermove',move);canvas.addEventListener('pointerup',up);});
window.addEventListener('resize',()=>{if(activeProject())fitScreen();});

async function init(){buildTools();updateSaveUi();try{await Promise.all([buildMenus(),loadDocumentTemplates()]);}catch(error){toast(error.message);}}
init();
